// --- ALGORITMO 1: BASE ---
long long zaino_base(int n, int W, const std::vector<int> &pesi, const std::vector<int> &valori, std::vector<std::vector<long long>> &dp)
{
 // Scansione bottom-up: per ogni oggetto i e capacità j
 // applichiamo la relazione di ricorrenza di Bellman
 for (int i = 1; i <= n; ++i)
 {
 for (int j = 1; j <= W; ++j)
 {
 if (pesi[i - 1] <= j)
 {
 // Possiamo inserire l'oggetto: scegliamo il massimo tra non inserirlo o inserirlo
 dp[i][j] = std::max(dp[i - 1][j], dp[i - 1][j - pesi[i - 1]] + valori[i - 1]);
 }
 else
 {
 // L'oggetto pesa più della capacità corrente, non può essere inserito
 dp[i][j] = dp[i - 1][j];
 }
 }
 }
 return dp[n][W];
}

// --- RICOSTRUZIONE SOLUZIONE (BACKTRACKING) ---
std::vector<int> ricostruisci_soluzione(int n, int W, const std::vector<int> &pesi, const std::vector<std::vector<long long>> &dp)
{
 std::vector<int> scelti;
 int j = W;
 for (int i = n; i > 0; --i)
 {
 if (dp[i][j] != dp[i - 1][j])
 {
 scelti.push_back(i - 1); // Indice 0-based dell'oggetto preso
 j -= pesi[i - 1];
 }
 }
 std::reverse(scelti.begin(), scelti.end());
 return scelti;
}

