// --- ALGORITMO 2: OTTIMIZZATO ---
long long zaino_ottimizzato(int n, int W, const std::vector<int> &pesi, const std::vector<int> &valori)
{
 std::vector<long long> dp(W + 1, 0);
 // Scansione bottom-up ottimizzata nello spazio
 // Iteriamo a ritroso sulla capacità per evitare il riutilizzo degli oggetti
 for (int i = 0; i < n; ++i)
 {
 for (int j = W; j >= pesi[i]; --j)
 {
 dp[j] = std::max(dp[j], dp[j - pesi[i]] + valori[i]);
 }
 }
 return dp[W];
}

